function EdgeItem({ item, t }) {
  const Icon = item.icon;

  return (
    <div className="flex gap-4 border-b border-[#E1E7F6] py-4 first:pt-0  sm:gap-5 sm:py-6">
      <span className="flex h-11 w-11 shrink-0 items-center justify-center"
        style={{
          borderRadius: "10px",
          border: "1px solid #E1E7F6",
          background: "#E1E7F6",
        }}
      >
        <Icon className="h-5 w-5" />
      </span>

      <div className="min-w-0">
        <h3 className="HeadingH5 font-semibold text-[#000]">
          {t(item.titleKey, item.title)}
        </h3>
        <p className="text-xs mt-2 font-normal leading-[1.65] text-[#666666] sm:mt-2.5">
          {t(item.descriptionKey, item.description)}
        </p>
      </div>
    </div>
  );
}

export default function WhyGtcGroupEdgeSection() {
  const t = usePathTranslation("whyGtcGroupPage.edgeSection");

  return (
    <section className=" py-8 md:py-16">
      <div className="container min-w-0 max-w-full">
        <div className="mx-auto grid max-w-6xl items-start gap-10 lg:grid-cols-[minmax(0,0.88fr)_minmax(0,1.12fr)] lg:gap-12 xl:gap-16">
          <div className="min-w-0 text-center md:text-left">
            <SectionEyebrow variant="compact" className="capitalize tracking-[0.3em]">
              {t("eyebrow", "Our Edge")}
            </SectionEyebrow>

            <h2 className="HeadingH1 mt-4 max-w-[300px] font-semibold leading-[1.2] text-[#000]">
              {t("title", "What makes GTC different")}
            </h2>

            <p className="Text mt-5 max-w-md font-normal leading-[1.7] text-[#000032]/60 md:mt-6">
              {t(
                "description",
                "In an industry full of similar-sounding firms, GTC Group is built differently — from our ownership structure to how we custody your assets."
              )}
            </p>

            <div className="mt-10 max-w-[280px] mx-auto md:mx-0 md:mt-12">
              <Image
                src={DOTS_SRC}
                alt=""
                width={280}
                height={140}
                className="h-auto w-full object-contain"
              />
            </div>
          </div>

          <div className="min-w-0">
            {EDGE_ITEMS.map((item) => (
              <EdgeItem key={item.key} item={item} t={t} />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
